import React, { useState, useEffect } from 'react';
import { Check, Plus, Search, ArrowUpDown, Edit, Trash2, XCircle } from 'lucide-react';

// Colors from the poster
const colors = {
  primary: '#f7abff',    // Pink background
  secondary: '#2f2a2f',  // Dark gray/black
  accent: '#3CDFFF',     // Cyan blue accent
  darkAccent: '#620f87', // Deep purple
  light: '#f9f9f9',      // White text
  midGray: '#797979',    // Mid gray
  successGreen: '#4ADE80',
  warningOrange: '#F97316',
  errorRed: '#EF4444'
};

const TasksPage = ({ tasks, milestones, onAddTask, onUpdateTask, onDeleteTask }) => {
  // State for filtering and sorting
  const [searchTerm, setSearchTerm] = useState('');
  const [milestoneFilter, setMilestoneFilter] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');
  const [sortBy, setSortBy] = useState({ field: 'id', direction: 'asc' });
  
  // State for new task form
  const [showAddTaskForm, setShowAddTaskForm] = useState(false);
  const [newTask, setNewTask] = useState({
    name: '',
    milestone: '',
    completed: false
  });
  
  // State for edit task
  const [editingTask, setEditingTask] = useState(null);
  
  // Handle form input changes
  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewTask({
      ...newTask,
      [name]: type === 'checkbox' ? checked : value
    });
  };
  
  // Handle edit input changes
  const handleEditInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setEditingTask({
      ...editingTask,
      [name]: type === 'checkbox' ? checked : value
    });
  };
  
  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    onAddTask(newTask);
    setNewTask({
      name: '',
      milestone: '',
      completed: false
    });
    setShowAddTaskForm(false);
  };
  
  // Handle edit form submission
  const handleEditSubmit = (e) => {
    e.preventDefault();
    onUpdateTask(editingTask.id, editingTask);
    setEditingTask(null);
  };
  
  // Handle sorting
  const handleSort = (field) => {
    setSortBy(prev => ({
      field,
      direction: prev.field === field && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };
  
  // Filter and sort tasks
  const filteredAndSortedTasks = tasks
    .filter(task => {
      // Search filter
      const matchesSearch = task.name.toLowerCase().includes(searchTerm.toLowerCase());
      
      // Milestone filter
      const matchesMilestone = milestoneFilter === 'All' || task.milestone === milestoneFilter;
      
      // Status filter
      const matchesStatus = statusFilter === 'All' || 
        (statusFilter === 'Completed' && task.completed) ||
        (statusFilter === 'Not Started' && !task.completed);
      
      return matchesSearch && matchesMilestone && matchesStatus;
    })
    .sort((a, b) => {
      const direction = sortBy.direction === 'asc' ? 1 : -1;
      
      if (sortBy.field === 'name') {
        return direction * a.name.localeCompare(b.name);
      }
      
      if (sortBy.field === 'milestone') {
        return direction * a.milestone.localeCompare(b.milestone);
      }
      
      // Default to sorting by id
      return direction * (a.id - b.id);
    });
  
  return (
    <div className="rounded-lg p-4" style={{ backgroundColor: colors.secondary }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-bold text-white mb-2">Tasks</h2>
          <p className="text-gray-400">Manage and track production tasks across milestones</p>
        </div>
        
        <button 
          className="px-4 py-2 rounded flex items-center"
          style={{ backgroundColor: colors.accent }}
          onClick={() => setShowAddTaskForm(true)}
        >
          <Plus className="h-4 w-4 mr-1" />
          <span>Add Task</span>
        </button>
      </div>
      
      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Search tasks..."
            className="bg-gray-800 text-white pl-10 pr-4 py-2 rounded w-full border border-gray-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        
        <select
          value={milestoneFilter}
          onChange={(e) => setMilestoneFilter(e.target.value)}
          className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700"
        >
          <option value="All">All Milestones</option>
          {milestones.map(milestone => (
            <option key={milestone.id} value={milestone.name}>{milestone.name}</option>
          ))}
        </select>
        
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700"
        >
          <option value="All">All Statuses</option>
          <option value="Completed">Completed</option>
          <option value="Not Started">Not Started</option>
        </select>
      </div>
      
      {/* Tasks table */}
      <div className="bg-gray-900 rounded-lg overflow-hidden mb-6">
        <table className="w-full text-left">
          <thead>
            <tr className="border-b border-gray-800">
              <th className="px-4 py-3 text-gray-400">Status</th>
              <th 
                className="px-4 py-3 text-gray-400 cursor-pointer"
                onClick={() => handleSort('name')}
              >
                <div className="flex items-center">
                  Task Name
                  {sortBy.field === 'name' && (
                    <ArrowUpDown className="h-4 w-4 ml-1" />
                  )}
                </div>
              </th>
              <th 
                className="px-4 py-3 text-gray-400 cursor-pointer"
                onClick={() => handleSort('milestone')}
              >
                <div className="flex items-center">
                  Milestone
                  {sortBy.field === 'milestone' && (
                    <ArrowUpDown className="h-4 w-4 ml-1" />
                  )}
                </div>
              </th>
              <th className="px-4 py-3 text-gray-400 text-center">Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedTasks.length === 0 ? (
              <tr>
                <td colSpan="4" className="px-4 py-8 text-center text-gray-400">
                  No tasks found. Add a new task or adjust your filters.
                </td>
              </tr>
            ) : (
              filteredAndSortedTasks.map(task => (
                <tr key={task.id} className="border-b border-gray-800 hover:bg-gray-800">
                  <td className="px-4 py-3">
                    <div 
                      className="cursor-pointer"
                      onClick={() => onUpdateTask(task.id, { ...task, completed: !task.completed })}
                    >
                      {task.completed ? 
                        <div className="h-6 w-6 rounded-full bg-green-500 flex items-center justify-center">
                          <Check className="h-4 w-4 text-white" />
                        </div> : 
                        <div className="h-6 w-6 rounded-full border border-gray-500" />
                      }
                    </div>
                  </td>
                  <td className={`px-4 py-3 ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
                    {task.name}
                  </td>
                  <td className="px-4 py-3 text-gray-400">
                    {task.milestone}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="flex justify-center space-x-2">
                      <button 
                        className="p-1 rounded bg-gray-700 hover:bg-gray-600"
                        onClick={() => setEditingTask(task)}
                      >
                        <Edit className="h-4 w-4 text-white" />
                      </button>
                      <button 
                        className="p-1 rounded bg-gray-700 hover:bg-red-900"
                        onClick={() => onDeleteTask(task.id)}
                      >
                        <Trash2 className="h-4 w-4 text-white" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      
      {/* Add Task Modal */}
      {showAddTaskForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-white">Add New Task</h3>
              <button 
                className="text-gray-400 hover:text-white"
                onClick={() => setShowAddTaskForm(false)}
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            
            <form onSubmit={handleSubmit}>
              <div className="space-y-4">
                <div>
                  <label className="block text-gray-400 mb-1">Task Name</label>
                  <input 
                    type="text"
                    name="name"
                    value={newTask.name}
                    onChange={handleInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-gray-400 mb-1">Milestone</label>
                  <select
                    name="milestone"
                    value={newTask.milestone}
                    onChange={handleInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                  >
                    <option value="" disabled>Select a milestone</option>
                    {milestones.map(milestone => (
                      <option key={milestone.id} value={milestone.name}>{milestone.name}</option>
                    ))}
                  </select>
                </div>
                
                <div className="flex items-center">
                  <input 
                    type="checkbox"
                    name="completed"
                    id="completed"
                    checked={newTask.completed}
                    onChange={handleInputChange}
                    className="h-4 w-4 mr-2"
                  />
                  <label htmlFor="completed" className="text-white">Mark as completed</label>
                </div>
                
                <div className="flex justify-end">
                  <button 
                    type="button"
                    onClick={() => setShowAddTaskForm(false)}
                    className="px-4 py-2 rounded border border-gray-700 text-gray-400 mr-2"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="px-4 py-2 rounded text-white"
                    style={{ backgroundColor: colors.accent }}
                  >
                    Add Task
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
      
      {/* Edit Task Modal */}
      {editingTask && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-gray-900 rounded-lg p-6 max-w-md w-full">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-white">Edit Task</h3>
              <button 
                className="text-gray-400 hover:text-white"
                onClick={() => setEditingTask(null)}
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
            
            <form onSubmit={handleEditSubmit}>
              <div className="space-y-4">
                <div>
                  <label className="block text-gray-400 mb-1">Task Name</label>
                  <input 
                    type="text"
                    name="name"
                    value={editingTask.name}
                    onChange={handleEditInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-gray-400 mb-1">Milestone</label>
                  <select
                    name="milestone"
                    value={editingTask.milestone}
                    onChange={handleEditInputChange}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                    required
                  >
                    {milestones.map(milestone => (
                      <option key={milestone.id} value={milestone.name}>{milestone.name}</option>
                    ))}
                  </select>
                </div>
                
                <div className="flex items-center">
                  <input 
                    type="checkbox"
                    name="completed"
                    id="editCompleted"
                    checked={editingTask.completed}
                    onChange={handleEditInputChange}
                    className="h-4 w-4 mr-2"
                  />
                  <label htmlFor="editCompleted" className="text-white">Mark as completed</label>
                </div>
                
                <div className="flex justify-end">
                  <button 
                    type="button"
                    onClick={() => setEditingTask(null)}
                    className="px-4 py-2 rounded border border-gray-700 text-gray-400 mr-2"
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit"
                    className="px-4 py-2 rounded text-white"
                    style={{ backgroundColor: colors.accent }}
                  >
                    Save Changes
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TasksPage;
